{"sql":"WITH w AS (
  SELECT week, customer_id, sum(gmv_amount) AS gmv, count(DISTINCT order_id) AS orders
  FROM order_lines
  WHERE week IN ('2011-W40','2011-W41') AND customer_id IS NOT NULL
  GROUP BY 1,2
), r AS (
  SELECT *, row_number() OVER (PARTITION BY week ORDER BY gmv DESC, customer_id) AS rn FROM w
)
SELECT week, customer_id, round(gmv,2) AS gmv, orders, rn
FROM r WHERE rn <= 12 ORDER BY week, rn","purpose":"查看 2011-W40/W41 两周各客户 GMV 排名前 12，核对数量级与订单数"}
